     1	<!DOCTYPE html>
     2	<html lang="en">
     3	<head>
     4	<meta charset="utf-8">
     5	<meta name="viewport" content="width=device-width, initial-scale=1">
     6	<title>Todos</title>
     7	<style>
     8	  * { box-sizing: border-box; }
     9	  body {
    10	    margin: 0;
    11	    font: 16px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    12	    background: #f5f5f4;
    13	    color: #1c1917;
    14	  }
    15	  main {
    16	    max-width: 32rem;
    17	    margin: 3rem auto;
    18	    padding: 0 1rem;
    19	  }
    20	  h1 { font-size: 1.5rem; margin: 0 0 1rem; }
    21	  form { display: flex; flex-wrap: wrap; gap: 0.5rem; }
    22	  input[type="text"] { flex: 1 1 8rem; }
    23	  input[type="text"], input[type="search"], input[type="date"], select {
    24	    min-width: 0;
    25	    padding: 0.6rem 0.75rem;
    26	    font: inherit;
    27	    border: 1px solid #d6d3d1;
    28	    border-radius: 6px;
    29	    background: #fff;
    30	  }
    31	  input[type="date"], select { color: #57534e; }
    32	  input[type="text"]:focus, input[type="search"]:focus, input[type="date"]:focus, select:focus { outline: 2px solid #2563eb; outline-offset: -1px; border-color: transparent; }
    33	  button {
    34	    font: inherit;
    35	    padding: 0.6rem 1rem;
    36	    border: 0;
    37	    border-radius: 6px;
    38	    cursor: pointer;
    39	  }
    40	  .add { background: #2563eb; color: #fff; }
    41	  .add:hover { background: #1d4ed8; }
    42	  ul { list-style: none; margin: 1.25rem 0 0; padding: 0; }
    43	  li {
    44	    display: flex;
    45	    align-items: center;
    46	    gap: 0.75rem;
    47	    padding: 0.6rem 0.75rem;
    48	    background: #fff;
    49	    border: 1px solid #e7e5e4;
    50	    border-radius: 6px;
    51	    margin-bottom: 0.5rem;
    52	  }
    53	  .text { flex: 1; overflow-wrap: anywhere; }
    54	  .delete { background: transparent; color: #b91c1c; padding: 0.3rem 0.6rem; }
    55	  .delete:hover { background: #fee2e2; }
    56	  .empty { color: #78716c; margin-top: 1.25rem; }
    57	  .filters { display: flex; gap: 0.25rem; margin-top: 1rem; }
    58	  .filters button { background: transparent; color: #57534e; padding: 0.3rem 0.75rem; }
    59	  .filters button:hover { background: #e7e5e4; }
    60	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; }
    61	  .search { display: block; width: 100%; margin-top: 0.75rem; }
    62	  .bulk { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 0.25rem; margin-top: 0.75rem; }
    63	  .bulk button { background: transparent; color: #57534e; padding: 0.3rem 0.75rem; }
    64	  .bulk button:hover { background: #e7e5e4; }
    65	  li input.edit { flex: 1 1 auto; padding: 0.2rem 0.4rem; }
    66	  .toggle { width: 1.1rem; height: 1.1rem; margin: 0; flex: none; cursor: pointer; accent-color: #2563eb; }
    67	  li[data-completed="true"] .text { color: #a8a29e; text-decoration: line-through; }
    68	  .due { flex: none; font-size: 0.85rem; color: #78716c; white-space: nowrap; }
    69	  /* Priority is a neutral text label; colour is reserved for the overdue highlight. */
    70	  .priority { flex: none; font-size: 0.75rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.03em; padding: 0.1rem 0.4rem; border-radius: 4px; color: #57534e; background: #f5f5f4; }
    71	  li[data-overdue="true"] { border-color: #f87171; }
    72	  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }
    73	</style>
    74	</head>
    75	<body>
    76	<main>
    77	  <h1>Todos</h1>
    78	  <form id="todo-form" autocomplete="off">
    79	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo">
    80	    <input data-testid="todo-due" type="date" aria-label="Due date (optional)">
    81	    <select data-testid="todo-priority" aria-label="Priority">
    82	      <option value="low">Low</option>
    83	      <option value="med" selected>Med</option>
    84	      <option value="high">High</option>
    85	    </select>
    86	    <button data-testid="todo-add" class="add" type="submit">Add</button>
    87	  </form>
    88	  <div class="filters" role="group" aria-label="Filter todos">
    89	    <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
    90	    <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
    91	    <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
    92	  </div>
    93	  <input data-testid="search-input" class="search" type="search" placeholder="Search todos" aria-label="Search todos">
    94	  <div class="bulk" role="group" aria-label="Bulk actions">
    95	    <button data-testid="bulk-mark-all" type="button">Mark all complete</button>
    96	    <button data-testid="bulk-clear-completed" type="button">Clear completed</button>
    97	  </div>
    98	  <ul data-testid="todo-list"></ul>
    99	  <p class="empty" hidden>No todos yet.</p>
   100	</main>
   101	<script>
   102	(function () {
   103	  var STORAGE_KEY = 'todos';
   104	  var form = document.getElementById('todo-form');
   105	  var input = document.querySelector('[data-testid="todo-input"]');
   106	  var dueInput = document.querySelector('[data-testid="todo-due"]');
   107	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
   108	  var list = document.querySelector('[data-testid="todo-list"]');
   109	  var empty = document.querySelector('.empty');
   110	  var filterButtons = document.querySelectorAll('[data-filter]');
   111	  var searchInput = document.querySelector('[data-testid="search-input"]');
   112	  var markAllButton = document.querySelector('[data-testid="bulk-mark-all"]');
   113	  var clearCompletedButton = document.querySelector('[data-testid="bulk-clear-completed"]');
   114	  var filter = 'all';
   115	  var query = '';
   116	  var editingId = null;
   117	
   118	  function load() {
   119	    try {
   120	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
   121	      if (!Array.isArray(data)) return [];
   122	      return data.filter(function (t) {
   123	        return t && typeof t.id === 'string' && typeof t.text === 'string';
   124	      }).map(function (t) {
   125	        t.completed = t.completed === true;
   126	        t.due = isDateString(t.due) ? t.due : null;
   127	        t.priority = isPriority(t.priority) ? t.priority : DEFAULT_PRIORITY;
   128	        return t;
   129	      });
   130	    } catch (e) {
   131	      return [];
   132	    }
   133	  }
   134	
   135	  function save() {
   136	    try {
   137	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
   138	    } catch (e) {
   139	      // Storage unavailable or full; keep working in memory.
   140	    }
   141	  }
   142	
   143	  var PRIORITIES = ['low', 'med', 'high'];
   144	  var DEFAULT_PRIORITY = 'med';
   145	  var PRIORITY_LABELS = { low: 'Low', med: 'Med', high: 'High' };
   146	
   147	  function isPriority(value) {
   148	    return PRIORITIES.indexOf(value) !== -1;
   149	  }
   150	
   151	  function makeId() {
   152	    if (window.crypto && typeof crypto.randomUUID === 'function') {
   153	      try { return crypto.randomUUID(); } catch (e) { /* fall through */ }
   154	    }
   155	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
   156	  }
   157	
   158	  // Due date rule (project decision): `due` is a plain 'YYYY-MM-DD' string
   159	  // holding a LOCAL calendar date, or null. Never parse it with `new Date(str)`
   160	  // (that reads it as UTC midnight). Overdue means due < today's local date,
   161	  // compared as strings; a todo due today is never overdue.
   162	  function isDateString(value) {
   163	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value);
   164	  }
   165	
   166	  function pad(n) {
   167	    return (n < 10 ? '0' : '') + n;
   168	  }
   169	
   170	  function todayLocal() {
   171	    var d = new Date();
   172	    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
   173	  }
   174	
   175	  function isOverdue(todo, today) {
   176	    return todo.due !== null && todo.due < today;
   177	  }
   178	
   179	  function formatDue(due) {
   180	    var parts = due.split('-');
   181	    var local = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
   182	    return local.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
   183	  }
   184	
   185	  // Ordering rule (project decision): completed todos always sit below all
   186	  // active todos. Within each group, higher priority comes first
   187	  // (high, med, low); equal priority keeps insertion order, oldest first.
   188	  // `todos` is stored in insertion order and never reordered.
   189	  var PRIORITY_RANK = { high: 0, med: 1, low: 2 };
   190	
   191	  function ordered() {
   192	    return todos.map(function (t, i) { return { todo: t, index: i }; })
   193	      .sort(function (a, b) {
   194	        return (a.todo.completed - b.todo.completed) ||
   195	          (PRIORITY_RANK[a.todo.priority] - PRIORITY_RANK[b.todo.priority]) ||
   196	          (a.index - b.index);
   197	      })
   198	      .map(function (entry) { return entry.todo; });
   199	  }
   200	
   201	  // Search combines with the status filter: a todo is shown only if it passes
   202	  // both. Matching is a case-insensitive substring test on the todo text.
   203	  function visible(todo) {
   204	    if (filter === 'active' && todo.completed) return false;
   205	    if (filter === 'completed' && !todo.completed) return false;
   206	    return query === '' || todo.text.toLowerCase().indexOf(query) !== -1;
   207	  }
   208	
   209	  function render() {
   210	    list.textContent = '';
   211	    var shown = ordered().filter(visible);
   212	    var today = todayLocal();
   213	    renderedDay = today;
   214	    shown.forEach(function (todo) {
   215	      var li = document.createElement('li');
   216	      li.setAttribute('data-testid', 'todo-item');
   217	      li.setAttribute('data-id', todo.id);
   218	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
   219	      li.setAttribute('data-priority', todo.priority);
   220	      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
   221	
   222	      var box = document.createElement('input');
   223	      box.type = 'checkbox';
   224	      box.className = 'toggle';
   225	      box.setAttribute('data-testid', 'todo-toggle');
   226	      box.setAttribute('aria-label', 'Mark "' + todo.text + '" complete');
   227	      box.checked = todo.completed;
   228	      box.addEventListener('change', function () { toggle(todo.id); });
   229	
   230	      var span = document.createElement('span');
   231	      span.className = 'text';
   232	      span.setAttribute('data-testid', 'todo-text');
   233	      span.textContent = todo.text;
   234	      span.addEventListener('dblclick', function () { startEdit(todo.id, span); });
   235	
   236	      var del = document.createElement('button');
   237	      del.type = 'button';
   238	      del.className = 'delete';
   239	      del.setAttribute('data-testid', 'todo-delete');
   240	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
   241	      del.textContent = 'Delete';
   242	      del.addEventListener('click', function () { remove(todo.id); });
   243	
   244	      li.appendChild(box);
   245	      var priority = document.createElement('span');
   246	      priority.className = 'priority';
   247	      priority.textContent = PRIORITY_LABELS[todo.priority];
   248	
   249	      li.appendChild(span);
   250	      li.appendChild(priority);
   251	      if (todo.due) {
   252	        var due = document.createElement('time');
   253	        due.className = 'due';
   254	        due.setAttribute('data-testid', 'todo-due-date');
   255	        due.setAttribute('datetime', todo.due);
   256	        due.textContent = (isOverdue(todo, today) ? 'Overdue: ' : 'Due ') + formatDue(todo.due);
   257	        li.appendChild(due);
   258	      }
   259	      li.appendChild(del);
   260	      list.appendChild(li);
   261	    });
   262	    if (todos.length === 0) {
   263	      empty.textContent = 'No todos yet.';
   264	    } else if (query !== '') {
   265	      empty.textContent = 'No todos match your search.';
   266	    } else if (filter === 'active') {
   267	      empty.textContent = 'No active todos.';
   268	    } else {
   269	      empty.textContent = 'No completed todos.';
   270	    }
   271	    empty.hidden = shown.length > 0;
   272	
   273	    filterButtons.forEach(function (btn) {
   274	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
   275	    });
   276	  }
   277	
   278	  function add(text, due, priority) {
   279	    text = text.trim();
   280	    if (!text) return false;
   281	    todos.push({
   282	      id: makeId(),
   283	      text: text,
   284	      completed: false,
   285	      due: isDateString(due) ? due : null,
   286	      priority: isPriority(priority) ? priority : DEFAULT_PRIORITY,
   287	      createdAt: Date.now()
   288	    });
   289	    save();
   290	    render();
   291	    return true;
   292	  }
   293	
   294	  function remove(id) {
   295	    todos = todos.filter(function (t) { return t.id !== id; });
   296	    save();
   297	    render();
   298	  }
   299	
   300	  function toggle(id) {
   301	    todos.forEach(function (t) {
   302	      if (t.id === id) t.completed = !t.completed;
   303	    });
   304	    save();
   305	    render();
   306	  }
   307	
   308	  // Bulk actions apply to every todo, ignoring the current filter and search.
   309	  // They only change `completed` or drop entries; the array keeps its
   310	  // insertion order, so ordered() still applies the ordering rule.
   311	  function markAll() {
   312	    todos.forEach(function (t) { t.completed = true; });
   313	    save();
   314	    render();
   315	  }
   316	
   317	  function clearCompleted() {
   318	    todos = todos.filter(function (t) { return !t.completed; });
   319	    save();
   320	    render();
   321	  }
   322	
   323	  function find(id) {
   324	    for (var i = 0; i < todos.length; i++) {
   325	      if (todos[i].id === id) return todos[i];
   326	    }
   327	    return null;
   328	  }
   329	
   330	  // Inline editing: double-click swaps the text for an input. Enter or blur
   331	  // commits, Escape cancels. An empty result cancels rather than deletes.
   332	  // On commit the row is patched in place instead of re-rendered, so a click
   333	  // that caused the blur (e.g. on another row's checkbox) still lands.
   334	  function startEdit(id, span) {
   335	    var todo = find(id);
   336	    if (!todo || editingId !== null) return;
   337	    editingId = id;
   338	    var li = span.parentNode;
   339	    var field = document.createElement('input');
   340	    field.type = 'text';
   341	    field.className = 'edit';
   342	    field.setAttribute('data-testid', 'todo-edit-input');
   343	    field.setAttribute('aria-label', 'Edit todo');
   344	    field.value = todo.text;
   345	    var finished = false;
   346	
   347	    function finish(commit) {
   348	      if (finished) return;
   349	      finished = true;
   350	      editingId = null;
   351	      var text = field.value.trim();
   352	      if (commit && text && text !== todo.text) {
   353	        todo.text = text;
   354	        save();
   355	        if (!visible(todo)) {
   356	          render();
   357	          return;
   358	        }
   359	        span.textContent = text;
   360	        li.querySelector('[data-testid="todo-toggle"]').setAttribute('aria-label', 'Mark "' + text + '" complete');
   361	        li.querySelector('[data-testid="todo-delete"]').setAttribute('aria-label', 'Delete "' + text + '"');
   362	      }
   363	      if (field.parentNode) li.replaceChild(span, field);
   364	      refreshIfNewDay();
   365	    }
   366	
   367	    field.addEventListener('keydown', function (e) {
   368	      if (e.key === 'Enter') {
   369	        e.preventDefault();
   370	        finish(true);
   371	      } else if (e.key === 'Escape') {
   372	        e.preventDefault();
   373	        finish(false);
   374	      }
   375	    });
   376	    field.addEventListener('blur', function () { finish(true); });
   377	
   378	    li.replaceChild(field, span);
   379	    field.focus();
   380	    field.setSelectionRange(field.value.length, field.value.length);
   381	  }
   382	
   383	  var todos = load();
   384	  var renderedDay = null;
   385	
   386	  // Re-render when the local date rolls over so overdue flags stay current.
   387	  function refreshIfNewDay() {
   388	    // Don't re-render under an open edit; finishing the edit calls this again.
   389	    if (editingId === null && todayLocal() !== renderedDay) render();
   390	  }
   391	  setInterval(refreshIfNewDay, 60 * 1000);
   392	  document.addEventListener('visibilitychange', function () {
   393	    if (!document.hidden) refreshIfNewDay();
   394	  });
   395	
   396	  filterButtons.forEach(function (btn) {
   397	    btn.addEventListener('click', function () {
   398	      filter = btn.getAttribute('data-filter');
   399	      render();
   400	    });
   401	  });
   402	
   403	  markAllButton.addEventListener('click', markAll);
   404	  clearCompletedButton.addEventListener('click', clearCompleted);
   405	
   406	  searchInput.addEventListener('input', function () {
   407	    query = searchInput.value.trim().toLowerCase();
   408	    render();
   409	  });
   410	
   411	  form.addEventListener('submit', function (e) {
   412	    e.preventDefault();
   413	    if (add(input.value, dueInput.value, priorityInput.value)) {
   414	      dueInput.value = '';
   415	      priorityInput.value = DEFAULT_PRIORITY;
   416	    }
   417	    input.value = '';
   418	    input.focus();
   419	  });
   420	
   421	  render();
   422	})();
   423	</script>
   424	</body>
   425	</html>
